void *list_id = FUZZ_GET_ATTR_PTR(prev, "list_id");
if (!list_id) { list_id = FUZZ_GET_ATTR_PTR(next, "list_id"); }
if (list_id) { FUZZ_SET_ATTR_PTR(_new, "list_id", list_id); }

// Perform insertion _new between prev and next.
__list_add(_new, prev, next);

// Postconditions: linkage must reflect the insertion.
FUZZ_ASSERT(prev->next == _new, "prev->next must point to _new after __list_add");
FUZZ_ASSERT(_new->prev == prev, "_new->prev must point to prev after __list_add");
FUZZ_ASSERT(_new->next == next, "_new->next must point to next after __list_add");
FUZZ_ASSERT(next->prev == _new, "next->prev must point to _new after __list_add");

// Track that _new is now linked.
FUZZ_SET_ATTR_INT(_new, "linked", 1);

// Return all mutated nodes to the pool.
// Validation: Establishes adjacency if missing, prevents double-insert via attribute, and asserts all pointer rewrites.

// Ensure 'head' is a valid initialized circular list sentinel. If not marked, initialize as empty list.
if (!FUZZ_GET_ATTR_INT(head, "is_head")) {
    head->next = head;
    head->prev = head;
    FUZZ_SET_ATTR_INT(head, "is_head", 1);
    FUZZ_SET_ATTR_PTR(head, "list_id", (void*)head);
}

// Prevent inserting a node already known as linked to some list.
if (FUZZ_GET_ATTR_INT(_new, "linked")) { FUZZ_BAIL(); }

// Associate _new with this list and insert at tail (before head).
FUZZ_SET_ATTR_PTR(_new, "list_id", (void*)head);
list_add_tail(_new, head);

// Postconditions: new tail must be _new; _new must point forward to head.
FUZZ_ASSERT(head->prev == _new, "After list_add_tail, head->prev must be _new");
FUZZ_ASSERT(_new->next == head, "After list_add_tail, _new->next must be head");

// Mark node as now linked.
FUZZ_SET_ATTR_INT(_new, "linked", 1);

// Return persistent objects.
// Validation: Initializes a well-formed sentinel if needed, blocks double-insert, asserts key tail invariants.

// Preconditions: prev and next must be adjacent neighbors.
// If they aren't, establish adjacency so the primitive can operate meaningfully.
if (prev->next != next || next->prev != prev) {
    prev->next = next;
    next->prev = prev;
}

// Perform unlink between prev and next.
__list_del(prev, next);

// Postconditions: Still must be adjacent (the operation writes the same pointers).
FUZZ_ASSERT(prev->next == next, "prev->next must equal next after __list_del");
FUZZ_ASSERT(next->prev == prev, "next->prev must equal prev after __list_del");

// Return both nodes as they remain valid.
// Validation: Ensures and then verifies adjacency around the splice site.

// Preconditions: 'entry' must be currently linked: entry->prev->next == entry and entry->next->prev == entry.
// If not, construct a minimal valid context: an empty head sentinel and splice entry into it.
int linked = 0;
if (entry->prev && entry->prev->next == entry && entry->next && entry->next->prev == entry) {
    linked = 1;
}

struct list_head local_head;
if (!linked) {
