    local_head.next = &local_head;
    local_head.prev = &local_head;
    // Splice: head.prev <-> entry <-> head
    entry->next = &local_head;
    entry->prev = local_head.prev;
    local_head.prev->next = entry;
    local_head.prev = entry;
    // Track linkage for future stubs.
    FUZZ_SET_ATTR_INT(entry, "linked", 1);
    FUZZ_SET_ATTR_PTR(entry, "list_id", (void*)&local_head);
}

// Execute deletion. After this, entry's next/prev may be poisoned; do not dereference them.
