import os
import random
from typing import List

def _rand_choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]

def _ident(rng: random.Random, min_len=1, max_len=12) -> str:
    first_chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_'
    rest_chars = first_chars + '0123456789'
    n = rng.randint(min_len, max_len)
    s = rng.choice(first_chars)
    s += ''.join(rng.choice(rest_chars) for _ in range(n-1))
    return s

def _sym(rng: random.Random) -> str:
    return 'CONFIG_' + _ident(rng, 1, 16).upper()

def _bool_default(rng: random.Random) -> str:
    # Common boolean/tristate defaults
    return _rand_choice(rng, ['y', 'n', 'm'])

def _quoted(rng: random.Random, min_len=0, max_len=40) -> str:
    # Simple quoted string without embedded quotes/newlines
    n = rng.randint(min_len, max_len)
    pool = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 -_./'
    s = ''.join(rng.choice(pool) for _ in range(n))
    return f'"{s}"'

def _hex_value(rng: random.Random) -> str:
    width = _rand_choice(rng, [1, 2, 4, 8])
    return '0x' + ''.join(rng.choice('0123456789abcdef') for _ in range(width))

def _int_value(rng: random.Random) -> str:
    if rng.random() < 0.2:
        return str(rng.randint(-10, 10))
    return str(rng.randint(0, 100000))

def _range_clause(rng: random.Random) -> str:
    if rng.random() < 0.5:
        lo = _int_value(rng)
        hi = _int_value(rng)
    else:
        lo = _hex_value(rng)
        hi = _hex_value(rng)
    # Ensure order logically (parser typically allows any, but keep valid)
    return f'    range {lo} {hi}\n'

def _depends_on_clause(rng: random.Random) -> str:
    # Generate simple dependency expressions
    ops = ['&&', '||']
    terms = []
    for _ in range(rng.randint(1, 3)):
        t = _sym(rng)
        if rng.random() < 0.3:
            t = f'! {t}'
        terms.append(t)
    expr = (' ' + _rand_choice(rng, ops) + ' ').join(terms)
    return f'    depends on {expr}\n'

def _select_imply_clause(rng: random.Random) -> str:
    kw = _rand_choice(rng, ['select', 'imply'])
    line = f'    {kw} {_sym(rng)}'
    if rng.random() < 0.5:
        # optional if condition
        cond_terms = []
        for _ in range(rng.randint(1, 2)):
            term = _sym(rng)
            if rng.random() < 0.3:
                term = f'! {term}'
            cond_terms.append(term)
        line += ' if ' + (' && '.join(cond_terms))
    return line + '\n'

def _prompt_clause(rng: random.Random) -> str:
    title = _quoted(rng, 3, 20)
    line = f'    prompt {title}'
    if rng.random() < 0.6:
        line += ' if ' + _sym(rng)
    return line + '\n'

def _help_block(rng: random.Random) -> str:
    # help or ---help--- blocks
    if rng.random() < 0.5:
        hdr = '    help\n'
    else:
        hdr = '    ---help---\n'
    lines = []
    for _ in range(rng.randint(1, 6)):
        n = rng.randint(0, 60)
        pool = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 ,.-_/()'
        lines.append('      ' + ''.join(rng.choice(pool) for _ in range(n)) + '\n')
    return hdr + ''.join(lines)

def _type_keyword(rng: random.Random) -> str:
    return _rand_choice(rng, ['bool', 'tristate', 'int', 'hex', 'string'])

def _default_clause(rng: random.Random, typ: str) -> str:
