    lines = []
    if rng.random() < 0.5:
        lines.append('# Automatically generated by generator\n')
    # optional mainmenu and comment
    if rng.random() < 0.8:
        lines.append(f'mainmenu {_quoted(rng, 5, 25)}\n\n')
    if rng.random() < 0.5:
        lines.append(f'menuconfig {_sym(rng)}\n    bool {_quoted(rng,5,20)}\n\n')
    return ''.join(lines)

def _generate_kconfig_text(rng: random.Random, target_size: int = 1024) -> str:
    parts = [_header_preamble(rng)]
    # Top-level mix of entries, menus, and choices
    while True:
        choice = rng.random()
        if choice < 0.5:
            parts.append(_config_entry(rng))
        elif choice < 0.75:
            parts.append(_menu_block(rng))
        else:
            parts.append(_choice_block(rng))
        current = ''.join(parts)
        if len(current) >= target_size or len(current) > 3800:
            break
    return ''.join(parts)

def generate(seed: int) -> bytes:
    """
    Generate a valid Kconfig file content as bytes. The fuzzing stubs consume this
    via FUZZ_PARAM_FILENAME; the harness will write our buffer to a file path it provides.
    The content aims to be syntactically valid and exercise scanner/parser features:
    - config entries with various types, defaults, ranges
    - depends on expressions, select/imply, prompts, help blocks
    - menu and choice blocks
    Size is capped under 4096 bytes.
    """
    rng = random.Random(seed)
    # Choose a target size varied per seed
    target = rng.randint(600, 2400)
    text = _generate_kconfig_text(rng, target_size=target)
    # Ensure reasonable final size cap
    data = text.encode('utf-8')
    if len(data) > 4096:
        data = data[:4096]
    # Guarantee trailing newline for clean EOF behavior
    if not data.endswith(b"\n"):
        data += b"\n"
    return data
